constexpr int sq(int x) {
  if (std::is_constant_evaluated()) return -1;
  return x * x;
}
int main() {
  constexpr int a = sq(10);
  int b = sq(10);
  const int n = 10; int c = sq(n);
  static int d = sq(10);
  const int e = sq(10);
  std::cout << a << ' ' << b << ' ' << c
            << ' ' << d << ' ' << e << '\n';
}

constexpr int sum_last(
    const std::array<int, 5>& a, int k) {
  int s = 0;
  for (int i = 5 - k; i <= 5; ++i) s += a[i];
  return s;
}
constexpr std::array<int, 5> fills{
    10, 20, 30, 40, 50};
static_assert(sum_last(fills, 2) == 90);
int main() {
  std::printf("%d\n", sum_last(fills, 2));
}

